// Procedural visual renderer for individual stage graphics
const StageGraphic: React.FC<{
  stageId: number;
  frame: number;
  secondaryColor: string;
  accentColor: string;
}> = ({ stageId, frame, secondaryColor, accentColor }) => {
  if (stageId === 1) {
    // Stage 1: Polychaete Worm inside tube
    const wormWave = Math.sin(frame * 0.12) * 4;
    return (
      <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <linearGradient id="tubeGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#403225" />
            <stop offset="50%" stopColor="#735d49" />
            <stop offset="100%" stopColor="#2b2118" />
          </linearGradient>
          <linearGradient id="wormGrad" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#ffb3b3" />
            <stop offset="50%" stopColor="#e67373" />
            <stop offset="100%" stopColor="#b33636" />
          </linearGradient>
        </defs>
        {/* Sediment Ground */}
        <ellipse cx="25" cy="85" rx="15" ry="8" fill="#1b2836" />
        <ellipse cx="50" cy="88" rx="20" ry="10" fill="#243447" />
        <ellipse cx="75" cy="86" rx="14" ry="7" fill="#1b2836" />
        <ellipse cx="60" cy="82" rx="12" ry="6" fill="#15202b" />

        {/* Tube */}
        <path d="M 42 55 L 45 85 L 55 85 L 58 55 Z" fill="url(#tubeGrad)" stroke="#1a120b" strokeWidth="1" />
        <ellipse cx="50" cy="55" rx="8" ry="2.5" fill="#2b2118" stroke="#1a120b" strokeWidth="1" />

        {/* Worm emerging */}
        <path
          d={`M 50 56 Q ${50 + wormWave} 40, ${48 + wormWave * 1.5} 25 Q ${46 + wormWave} 12, ${50 + wormWave * 0.5} 8`}
          fill="none"
          stroke="url(#wormGrad)"
          strokeWidth="6"
          strokeLinecap="round"
        />
        {/* Feelers */}
        <circle cx={50 + wormWave * 0.5} cy="8" r="3.5" fill="#e67373" />
        <path d={`M ${50 + wormWave * 0.5} 8 Q ${53 + wormWave} 3, ${55 + wormWave} 1`} fill="none" stroke="#ffb3b3" strokeWidth="0.8" />
        <path d={`M ${50 + wormWave * 0.5} 8 Q ${47 + wormWave} 3, ${44 + wormWave} 1`} fill="none" stroke="#ffb3b3" strokeWidth="0.8" />
      </svg>
    );
  }

  if (stageId === 2) {
    // Stage 2: Spore Release
    return (
      <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <radialGradient id="waterBG" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#0b223d" />
            <stop offset="100%" stopColor="#040e1a" />
          </radialGradient>
          <radialGradient id="sporeGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#e1f0ff" />
            <stop offset="70%" stopColor="#71b1f5" stopOpacity="0.8" />
            <stop offset="100%" stopColor="#2c75c4" stopOpacity="0" />
          </radialGradient>
        </defs>
        <circle cx="50" cy="50" r="45" fill="url(#waterBG)" opacity="0.6" />
        {Array.from({ length: 6 }).map((_, i) => {
          const seed = i * 29.87;
          const speed = 0.5 + (i % 3) * 0.2;
          const driftX = Math.sin(frame * 0.04 + seed) * 10;
          const driftY = -((frame * speed + seed) % 85);
          // Rewritten with >= to avoid parser confusion with < symbol in JSX
          const finalY = driftY >= -10 ? driftY : driftY + 100;
          const size = 3 + (i % 3) * 1.5;

          return (
            <g key={i} transform={`translate(${20 + (i * 12) + driftX}, ${10 + finalY})`}>
              <circle cx="0" cy="0" r={size * 2.2} fill="url(#sporeGlow)" />
              <circle cx="0" cy="0" r={size} fill="none" stroke="#a6d2ff" strokeWidth="0.8" />
              <ellipse cx={-size * 0.25} cy={-size * 0.1} rx={size * 0.2} ry={size * 0.12} fill="#4290e3" transform="rotate(-20)" />
              <ellipse cx={size * 0.25} cy={-size * 0.1} rx={size * 0.2} ry={size * 0.12} fill="#4290e3" transform="rotate(20)" />
            </g>
          );
        })}
      </svg>
    );
  }

  if (stageId === 3) {
    // Stage 3: Attachment Close-up
    return (
      <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <linearGradient id="gillFilament" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#991f1f" />
            <stop offset="50%" stopColor="#ff4d4d" />
            <stop offset="100%" stopColor="#801010" />
          </linearGradient>
        </defs>
        {Array.from({ length: 4 }).map((_, i) => {
          const y = 25 + i * 18;
          const sway = Math.sin(frame * 0.08 + i) * 2;
          return (
            <path
              key={i}
              d={`M 15 ${y} Q 45 ${y - 6 + sway}, 85 ${y + sway}`}
              fill="none"
              stroke="url(#gillFilament)"
              strokeWidth="5"
              strokeLinecap="round"
            />
          );
        })}
        {Array.from({ length: 3 }).map((_, i) => {
          const seed = i * 44.5;
          const pulse = 1 + Math.sin(frame * 0.1 + seed) * 0.15;
          const x = 35 + i * 15;
          const y = 25 + i * 18 + Math.sin(frame * 0.08 + i) * 2 - 3;

          return (
            <g key={i} transform={`translate(${x}, ${y}) scale(${pulse})`}>
              <circle cx="0" cy="0" r="4.5" fill="#71b1f5" opacity="0.4" />
              <circle cx="0" cy="0" r="2.5" fill="#e1f0ff" stroke="#2c75c4" strokeWidth="0.8" />
            </g>
          );
        })}
      </svg>
    );
  }

  if (stageId === 4) {
    // Stage 4: Bloodstream
    return (
      <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <linearGradient id="vesselWall" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#4a0808" />
            <stop offset="15%" stopColor="#a31c1c" />
            <stop offset="50%" stopColor="#2b0303" stopOpacity="0.1" />
            <stop offset="85%" stopColor="#a31c1c" />
            <stop offset="100%" stopColor="#4a0808" />
          </linearGradient>
        </defs>
        <rect x="5" y="15" width="90" height="70" rx="6" fill="url(#vesselWall)" stroke="#ff4d4d" strokeWidth="1" strokeOpacity="0.3" />
        {Array.from({ length: 5 }).map((_, i) => {
          const seed = i * 65.4;
          const speed = 0.8 + (i % 3) * 0.3;
          const flowX = ((frame * speed + seed) % 80);
          const y = 25 + (seed % 45);

          return (
            <ellipse
              key={i}
              cx={10 + flowX}
              cy={y}
              rx="5"
              ry="2.5"
              fill="#c22727"
              stroke="#eb5757"
              strokeWidth="0.5"
              transform={`rotate(25, ${10 + flowX}, ${y})`}
              opacity="0.8"
            />
          );
        })}
      </svg>
    );
  }

  if (stageId === 5) {
    // Stage 5: Intestinal Tract migration
    return (
      <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <linearGradient id="intestineGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#d96c6c" />
            <stop offset="50%" stopColor="#f7a1a1" />
            <stop offset="100%" stopColor="#9c4242" />
          </linearGradient>
        </defs>
        <path
          d="M 15 50 C 35 25, 65 25, 80 45 C 90 60, 70 80, 50 75 C 30 70, 15 80, 25 90"
          fill="none"
          stroke="url(#intestineGrad)"
          strokeWidth="12"
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity="0.9"
        />
        <circle cx="48" cy="42" r="3" fill="#71b1f5" stroke="#0f5099" strokeWidth="0.6" style={{ filter: "drop-shadow(0px 0px 3px #71b1f5)" }} />
        <circle cx="62" cy="65" r="3" fill="#71b1f5" stroke="#0f5099" strokeWidth="0.6" style={{ filter: "drop-shadow(0px 0px 3px #71b1f5)" }} />
      </svg>
    );
  }

  // Stage 6: Tissue death & anemia
  const alertPulse = 0.5 + Math.sin(frame * 0.1) * 0.3;
  return (
    <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
      <circle cx="50" cy="50" r="42" fill="#2d0a0a" opacity="0.8" />
      <g stroke="#ff4d4d" strokeWidth="0.8" fill="none" opacity="0.3">
        <polygon points="50,15 63,22.5 63,37.5 50,45 37,37.5 37,22.5" />
        <polygon points="63,37.5 76,45 76,60 63,67.5 50,60 50,45" />
        <polygon points="37,37.5 50,45 50,60 37,67.5 24,60 24,45" />
      </g>
      <circle cx="50" cy="50" r="24" fill="none" stroke={accentColor} strokeWidth="1" strokeDasharray="3,3" opacity={alertPulse} />
    </svg>
  );
};

// Main interactive stylized Salmon swimmer
const SalmonSwim: React.FC<{
  width: number;
  height: number;
  frame: number;
  isActive: boolean;
  accentColor: string;
}> = ({ width, height, frame, isActive, accentColor }) => {
  const sway = Math.sin(frame * 0.12) * 3;
  const swimX = Math.cos(frame * 0.05) * 6;
  const swimY = Math.sin(frame * 0.08) * 4;

  return (
    <div
      style={{
        position: "absolute",
        left: width * 0.1,
        top: height * 0.44,
        width: width * 0.8,
        height: height * 0.22,
        transform: `translate(${swimX}px, ${swimY}px) rotate(${sway}deg)`,
        transformOrigin: "center center",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        pointerEvents: "none",
        zIndex: 5,
        opacity: 0.9,
        transition: "none",
      }}
    >
      <svg viewBox="0 0 600 200" width="100%" height="100%" style={{ overflow: "visible" }}>
        <defs>
          <linearGradient id="salmonGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#415e7a" />
            <stop offset="40%" stopColor="#8cb4d9" />
            <stop offset="70%" stopColor="#b0cde8" />
            <stop offset="100%" stopColor="#4a6a8a" />
          </linearGradient>
          <linearGradient id="salmonBelly" x1="0%" y1="100%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#ffffff" stopOpacity={0.9} />
            <stop offset="50%" stopColor="#e2eaf0" stopOpacity={0.8} />
            <stop offset="100%" stopColor="#ffd4d4" stopOpacity={0.3} />
          </linearGradient>
          <linearGradient id="gillColor" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#ff1a1a" />
            <stop offset="100%" stopColor="#800000" />
          </linearGradient>
        </defs>

        {/* Caudal Fin */}
        <path d="M 500 100 Q 550 50, 565 35 Q 555 80, 542 100 Q 555 120, 565 165 Q 550 150, 500 100" fill="#31495e" opacity={0.8} />
        {/* Dorsal Fin */}
        <path d="M 285 64 Q 315 15, 335 30 Q 320 60, 310 64" fill="#3b566e" opacity={0.7} />
        {/* Anal Fin */}
        <path d="M 385 132 Q 415 170, 428 160 Q 412 135, 398 133" fill="#3b566e" opacity={0.65} />

        {/* Main Body */}
        <path
          d="M 60 100 C 110 50, 240 45, 380 60 C 450 68, 480 85, 500 100 C 480 115, 450 132, 380 140 C 240 155, 110 150, 60 100 Z"
          fill="url(#salmonGrad)"
        />
        {/* White Belly */}
        <path
          d="M 120 118 C 180 135, 300 138, 380 134 C 440 130, 480 118, 500 100 C 460 115, 360 125, 250 122 C 160 118, 120 118, 120 118 Z"
          fill="url(#salmonBelly)"
        />

        {/* Lateral Line */}
        <path d="M 62 100 Q 280 104, 498 100" fill="none" stroke="#1d3042" strokeWidth="1.2" strokeDasharray="3,3" opacity={0.4} />

        {/* Red Glowing Gill Arc */}
        <path
          d="M 152 82 C 142 90, 142 110, 152 118"
          fill="none"
          stroke="url(#gillColor)"
          strokeWidth="5"
          strokeLinecap="round"
          style={{
            filter: isActive ? "drop-shadow(0px 0px 8px #ff1a1a)" : "none",
          }}
        />

        {/* Eye */}
        <circle cx="110" cy="90" r="6" fill="#e6c300" stroke="#111" strokeWidth="1" />
        <circle cx="111" cy="89" r="2.5" fill="#111" />
        <circle cx="109" cy="87" r="1" fill="#fff" />

        {/* Mouth */}
        <path d="M 60 100 Q 82 104, 98 100" fill="none" stroke="#1d3042" strokeWidth="2" strokeLinecap="round" />

        {/* Gill Spotlight Ring */}
        {isActive && (
          <circle
            cx="145"
            cy="100"
            r="32"
            fill="none"
            stroke={accentColor}
            strokeWidth="2.5"
            strokeDasharray="6,4"
            style={{
              filter: `drop-shadow(0px 0px 8px ${accentColor})`,
            }}
          />
        )}
      </svg>
    </div>
  );
};

const CeratonovaLifecycle: React.FC<CeratonovaLifecycleProps> = ({
  backgroundColor = "#040b14",
  transparentBackground = false,
  durationInSeconds = 20,
  titleText = "CERATONOVA SHASTA",
  subtitleText = "A TWO-HOST LIFECYCLE",
  primaryColor = "#ffffff",
  secondaryColor = "#8cb4d9",
  accentColor = "#ff4d4d",
  glowOpacity = 0.6,
  animationSpeedMultiplier = 1.0,
  steps = [
    {
      id: 1,
      title: "POLYCHAETE WORM",
      desc: "Lives in riverbed sediment.",
    },
    {
      id: 2,
      title: "SPORE RELEASE",
      desc: "Infected worms release microscopic spores into water.",
    },
    {
      id: 3,
      title: "ATTACHMENT",
      desc: "Spores attach directly to the salmon's gills.",
    },
    {
      id: 4,
      title: "INFECTION",
      desc: "Spores penetrate and enter the bloodstream.",
    },
    {
      id: 5,
      title: "MIGRATION",
      desc: "Parasites migrate to the intestinal tract.",
    },
    {
      id: 6,
      title: "DISEASE",
      desc: "Causes severe tissue death and anemia in juvenile fish.",
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color parsing safety
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive diagram sizes
  const circleSize = Math.min(width, height) * 0.17;
  const R = circleSize / 2;

  // Coordinate mapping for the circles (matching original infographic perfectly)
  const layoutCoords = [
    { id: 1, x: 0.50, y: 0.32, align: "right" as const }, // Top Center
    { id: 2, x: 0.81, y: 0.42, align: "left" as const },  // Top Right
    { id: 3, x: 0.35, y: 0.55, align: "right" as const }, // Center Left (Gill)
    { id: 4, x: 0.18, y: 0.77, align: "center" as const },// Bottom Left
    { id: 5, x: 0.50, y: 0.77, align: "center" as const },// Bottom Center
    { id: 6, x: 0.82, y: 0.78, align: "center" as const },// Bottom Right
  ];

  // Dynamic timing structure based on duration
  const totalFrames = durationInSeconds * fps;
  const introEnd = totalFrames * 0.1;
  const cycleEnd = totalFrames * 0.85;
  const stageDuration = (cycleEnd - introEnd) / 6;

  // Calculate current active stage
  let activeStage = 0; // 0 = intro, 1..6 = active stages, 7 = final wrap-up
  if (frame < introEnd) {
    activeStage = 0;
  } else if (frame >= cycleEnd) {
    activeStage = 7;
  } else {
    activeStage = Math.floor((frame - introEnd) / stageDuration) + 1;
  }

  // Animation for headers
  const titleSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const titleY = interpolate(titleSpring, [0, 1], [-150, 0]);
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);

  // Generate deterministic particles for beautiful underwater ambient background
  const BACKGROUND_PARTICLES = 35;
  const ambientParticles = Array.from({ length: BACKGROUND_PARTICLES }).map((_, i) => {
    const seedX = random(`px-${i}`);
    const seedY = random(`py-${i}`);
    const seedSpeed = random(`pspeed-${i}`);
    const size = 3 + random(`psize-${i}`) * 6;
    
    const flowY = ((seedY * height - (frame * (0.8 + seedSpeed * 1.5) * animationSpeedMultiplier)) % height);
    const yPos = flowY < 0 ? flowY + height : flowY;
    const xPos = seedX * width + Math.sin(frame * 0.02 + seedX * 10) * 15;

    return { x: xPos, y: yPos, size };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, overflow: "hidden" }}>
      {/* Background Glow */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          background: "radial-gradient(circle at 50% 40%, #0c2038 0%, #030a14 75%)",
          opacity: 0.85,
        }}
      />

      {/* Ambient Floating Spores (Background) */}
      {ambientParticles.map((pt, idx) => (
        <div
          key={idx}
          style={{
            position: "absolute",
            left: pt.x,
            top: pt.y,
            width: pt.size,
            height: pt.size,
            borderRadius: "50%",
            backgroundColor: "#71b1f5",
            opacity: 0.25,
            filter: "blur(1px) drop-shadow(0px 0px 4px #71b1f5)",
            pointerEvents: "none",
            transition: "none",
          }}
        />
      ))}

      {/* SVG Connection Arrows between infographic steps */}
      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          zIndex: 4,
          overflow: "visible",
        }}
      >
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="8" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill={secondaryColor} />
          </marker>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="6" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Generate dynamic path lines */}
        {layoutCoords.map((pt, idx) => {
          if (idx === layoutCoords.length - 1) return null; // No path from last step to next in standard flow here, or loops back to 1
          const nextPt = layoutCoords[idx + 1];
          const x1 = pt.x * width;
          const y1 = pt.y * height;
          const x2 = nextPt.x * width;
          const y2 = nextPt.y * height;

          // Simple curve calculation
          const midX = (x1 + x2) / 2;
          const midY = (y1 + y2) / 2 - (idx === 1 ? 40 : -20); // Arc modifier
          const pathD = `M ${x1} ${y1} Q ${midX} ${midY}, ${x2} ${y2}`;

          const isActiveArrow = activeStage === pt.id;
          const pulseStroke = isActiveArrow ? secondaryColor : "rgba(140, 180, 217, 0.25)";
          const strokeWidthVal = isActiveArrow ? 3.5 : 2;

          return (
            <path
              key={idx}
              d={pathD}
              fill="none"
              stroke={pulseStroke}
              strokeWidth={strokeWidthVal}
              markerEnd="url(#arrowhead)"
              style={{
                filter: isActiveArrow ? "url(#glow)" : "none",
                transition: "none",
              }}
            />
          );
        })}

        {/* Loop back arrow from Step 6 to Step 1 */}
        {(() => {
          const pt6 = layoutCoords[5];
          const pt1 = layoutCoords[0];
          const x6 = pt6.x * width;
          const y6 = pt6.y * height;
          const x1 = pt1.x * width;
          const y1 = pt1.y * height;
          const loopPath = `M ${x6} ${y6} C ${width * 1.05} ${height * 0.7}, ${width * 0.95} ${height * 0.25}, ${x1 + 10} ${y1}`;
          const isLoopActive = activeStage === 6;

          return (
            <path
              d={loopPath}
              fill="none"
              stroke={isLoopActive ? secondaryColor : "rgba(140, 180, 217, 0.2)"}
              strokeWidth={isLoopActive ? 3 : 1.5}
              markerEnd="url(#arrowhead)"
              style={{
                filter: isLoopActive ? "url(#glow)" : "none",
                transition: "none",
              }}
            />
          );
        })()}
      </svg>

      {/* Header / Title block */}
      <div style={{ ...titleContainerStyle, transform: `translateY(${titleY}px)`, opacity: titleOpacity }}>
        <div
          style={{
            fontFamily: bebasFamily,
            fontSize: Math.min(width * 0.09, 85),
            fontWeight: "bold",
            color: primaryColor,
            letterSpacing: "4px",
            lineHeight: 0.9,
            textShadow: "0 0 10px rgba(255,255,255,0.15)",
          }}
        >
          {titleText.split(" ")[0]}
        </div>
        <div
          style={{
            fontFamily: bebasFamily,
            fontSize: Math.min(width * 0.12, 115),
            fontWeight: "bold",
            color: secondaryColor,
            letterSpacing: "6px",
            lineHeight: 1.0,
            marginTop: "4px",
            textShadow: `0 0 15px ${secondaryColor}33`,
          }}
        >
          {titleText.split(" ")[1] || "SHASTA"}
        </div>
        <div
          style={{
            fontFamily: montserratFamily,
            fontSize: Math.min(width * 0.032, 24),
            fontWeight: "600",
            color: primaryColor,
            letterSpacing: "5px",
            opacity: 0.8,
            marginTop: "12px",
          }}
        >
          {subtitleText}
        </div>
      </div>

      {/* Central Swimmer Salmon */}
      <SalmonSwim
        width={width}
        height={height}
        frame={frame}
        isActive={activeStage === 3}
        accentColor={accentColor}
      />

      {/* Render Lifecycle Stage Circular Nodes */}
      {layoutCoords.map((stage) => {
        const currentStep = steps.find((s) => s.id === stage.id) || {
          id: stage.id,
          title: "",
          desc: "",
        };
        const X = stage.x * width;
        const Y = stage.y * height;

        // Custom timing calculation per node
        const stageStartFrame = introEnd + (stage.id - 1) * stageDuration;
        const introProgress = spring({
          frame: frame - stage.id * 8, // staggered arrival
          fps,
          config: { damping: 15 },
        });

        const activePulse = activeStage === stage.id ? 1 + Math.sin(frame * 0.15) * 0.04 : 1.0;
        const scale = interpolate(introProgress, [0, 1], [0, activeStage === stage.id ? 1.15 : 1.0]) * activePulse;

        // Visual indicator styling
        const isActive = activeStage === stage.id;
        const isCompleted = activeStage > stage.id;
        const circleBorderColor = isActive
          ? secondaryColor
          : isCompleted
          ? `${secondaryColor}aa`
          : "rgba(255, 255, 255, 0.2)";

        const circleGlow = isActive
          ? `0 0 25px ${secondaryColor}${Math.floor(glowOpacity * 255).toString(16)}`
          : "none";

        const numberColor = isActive ? secondaryColor : isCompleted ? `${secondaryColor}cc` : "#ffffff66";
        const titleTextColor = isActive ? "#ffffff" : isCompleted ? "#ffffffbb" : "#ffffff44";
        const descTextColor = isActive ? "#ffffffcc" : isCompleted ? "#ffffff88" : "#ffffff22";

        // Side text block styling relative to host circle
        const isLeft = stage.align === "right";
        const isCenter = stage.align === "center";

        const textWidth = Math.min(width * 0.28, 220);

        const textStyle: React.CSSProperties = {
          fontFamily: montserratFamily,
          position: "absolute",
          display: "flex",
          flexDirection: "column",
          alignItems: isCenter ? "center" : isLeft ? "flex-end" : "flex-start",
          textAlign: stage.align,
          width: textWidth,
          pointerEvents: "none",
          transition: "none",
          ...(isCenter
            ? { top: R + 14, left: -textWidth / 2 + R }
            : isLeft
            ? { right: R * 2 + 15, top: -10 }
            : { left: R * 2 + 15, top: -10 }),
        };

        return (
          <div
            key={stage.id}
            style={{
              position: "absolute",
              left: X - R,
              top: Y - R,
              width: circleSize,
              height: circleSize,
              zIndex: isActive ? 12 : 6,
              transform: `scale(${scale})`,
              transition: "none",
            }}
          >
            {/* Inner Diagram Container */}
            <div
              style={{
                width: "100%",
                height: "100%",
                borderRadius: "50%",
                border: `2.5px solid ${circleBorderColor}`,
                boxShadow: circleGlow,
                backgroundColor: "rgba(4, 15, 28, 0.9)",
                overflow: "hidden",
                position: "relative",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                transition: "none",
              }}
            >
              <StageGraphic
                stageId={stage.id}
                frame={frame}
                secondaryColor={secondaryColor}
                accentColor={accentColor}
              />
            </div>

            {/* Step Caption Label */}
            <div style={textStyle}>
              <div
                style={{
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "baseline",
                  gap: "6px",
                  transition: "none",
                }}
              >
                <span style={{ fontFamily: bebasFamily, fontSize: Math.min(width * 0.04, 28), color: numberColor }}>
                  {stage.id}
                </span>
                <span
                  style={{
                    fontFamily: bebasFamily,
                    fontSize: Math.min(width * 0.026, 16),
                    color: titleTextColor,
                    letterSpacing: "1px",
                  }}
                >
                  {currentStep.title}
                </span>
              </div>
              <div
                style={{
                  fontSize: Math.min(width * 0.02, 11),
                  color: descTextColor,
                  marginTop: "3px",
                  lineHeight: 1.25,
                  fontWeight: "400",
                }}
              >
                {currentStep.desc}
              </div>
            </div>
          </div>
        );
      })}

      {/* Cinematic Highlight Banner at Bottom (Focusing Active Stage) */}
      {(() => {
        const activeStepData = steps.find((s) => s.id === activeStage);
        if (!activeStepData) return null;

        const activeStageFrame = frame - (introEnd + (activeStage - 1) * stageDuration);
        const bannerSpring = spring({
          frame: activeStageFrame,
          fps,
          config: { damping: 15, mass: 0.6 },
        });

        const bannerY = interpolate(bannerSpring, [0, 1], [30, 0], { extrapolateRight: "clamp" });
        const bannerOpacity = interpolate(bannerSpring, [0, 1], [0, 1], { extrapolateRight: "clamp" });

        return (
          <div
            style={{
              position: "absolute",
              bottom: height * 0.07,
              left: width * 0.08,
              width: width * 0.84,
              padding: "16px 20px",
              backgroundColor: "rgba(4, 14, 26, 0.9)",
              border: `1.5px solid ${secondaryColor}44`,
              borderRadius: 14,
              boxShadow: "0 10px 30px rgba(0,0,0,0.5)",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transform: `translateY(${bannerY}px)`,
              opacity: bannerOpacity,
              zIndex: 15,
              textAlign: "center",
              transition: "none",
            }}
          >
            <div
              style={{
                fontFamily: bebasFamily,
                fontSize: 18,
                color: secondaryColor,
                letterSpacing: "2px",
                marginBottom: 4,
              }}
            >
              STAGE {activeStepData.id}: {activeStepData.title}
            </div>
            <div
              style={{
                fontFamily: montserratFamily,
                fontSize: 13,
                color: primaryColor,
                lineHeight: 1.4,
                fontWeight: "300",
              }}
            >
              {activeStepData.desc}
            </div>
          </div>
        );
      })()}
    </AbsoluteFill>
  );
};

// Styling Object for title container
const titleContainerStyle: React.CSSProperties = {
  position: "absolute",
  top: "5%",
  left: "5%",
  width: "90%",
  textAlign: "center",
  zIndex: 10,
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  transition: "none",
};

export default CeratonovaLifecycle;